INSERT INTO `category` (`id`, `name`) VALUES
(0xab5edc96447d11f19dd676251f73c1ac, 'Active'),
(0xab5e4fd8447d11f19dd676251f73c1ac, 'Creative'),
(0xab5e9830447d11f19dd676251f73c1ac, 'Culture'),
(0xab5d858a447d11f19dd676251f73c1ac, 'Food & Drinks'),
(0xab5df772447d11f19dd676251f73c1ac, 'Nature');
INSERT INTO `activity` (`id`, `title`, `description`, `budget`, `duration`, `is_indoor`, `category_id`, `created_at`) VALUES
(0x84abc70c52c011f1ad3676251f73c1ac, 'Natural History Museum', 'Spend an afternoon moving through halls of fossils, minerals, and ancient life. The kind of place that makes you feel small in the best way. Go slowly and read the things that catch your eye. There is always something neither of you has noticed before.', '€', 180, 1, 0xab5df772447d11f19dd676251f73c1ac, '2026-05-18 15:50:23'),
(0x84abecdc52c011f1ad3676251f73c1ac, 'Planetarium Show', 'Lie back in a domed room and watch the universe projected above you. Quiet, perspective-shifting, and genuinely beautiful. A date that makes everything feel appropriately small. Check what shows are on and book in advance since sessions fill up quickly.', '€', 90, 1, 0xab5df772447d11f19dd676251f73c1ac, '2026-05-18 15:50:23'),
(0x84abed8652c011f1ad3676251f73c1ac, 'Butterfly House', 'Walk through a warm, humid greenhouse full of live butterflies landing wherever they please. Unhurried, colourful, and unexpectedly calming. Bring your camera and move slowly. One of those dates that feels like stepping into a completely different world for an hour.', '€€', 90, 1, 0xab5df772447d11f19dd676251f73c1ac, '2026-05-18 15:50:23'),
(0xab66cc3a447d11f19dd676251f73c1ac, 'Brunch at a Local Coffee Shop ', 'There is something special about a morning with nowhere to be. Pick a cozy café, order too much, and let the conversation flow over coffee and pastries. No phones, no rush. Just the two of you settling into the day together.', '€€', 120, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671dca447d11f19dd676251f73c1ac, 'Street Food Market Adventure', 'Wander through a local market and let your appetite lead the way. Share bites from different stalls, argue over which one was best, and discover a new favorite together. It is spontaneous, affordable, and always a good story.', '€', 90, 0, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671eb0447d11f19dd676251f73c1ac, 'Cook a Themed Dinner Together', 'Pick a cuisine neither of you cooks regularly and spend the evening making it from scratch. Divide the tasks, make a mess of the kitchen, and sit down to a meal that is entirely yours. The process is half the fun.', '€', 180, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671f0a447d11f19dd676251f73c1ac, 'Wine Tasting or Brewery Tour', 'Book a tasting session at a local winery or craft brewery and spend the afternoon sampling something new. You will learn a little, laugh a lot, and leave with a bottle to take home. A relaxed way to explore something you both enjoy.', '€€', 150, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671f64447d11f19dd676251f73c1ac, 'Bake Something from Scratch', 'Choose a recipe that feels a little ambitious and tackle it together. Divide the tasks, inevitably disagree on at least one step, and end up with something warm and homemade. Even if it does not come out perfect, it will still taste good.', '€', 120, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671f96447d11f19dd676251f73c1ac, 'Ice Cream Crawl', 'Map out three or four ice cream spots in your city and hit them all in one afternoon. Try something you would not normally order and share bites along the way. It is the kind of date that sounds silly and ends up being a favorite.', '€', 120, 0, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671fbe447d11f19dd676251f73c1ac, 'Chocolate Factory or Distillery Tour', 'Book a guided tour of a local chocolate maker or distillery and get a behind-the-scenes look at how things are made. There will be tastings, fun facts, and something to bring home. A date that is equal parts educational and delicious.', '€€', 120, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab671ffa447d11f19dd676251f73c1ac, 'Try a Cuisine You Have Never Had', 'Pick a restaurant serving food from a country neither of you knows well and order adventurously. Ask the staff for recommendations, share everything, and be open to being surprised. Some of the best meals come from saying yes to the unknown.', '€€', 90, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab672676447d11f19dd676251f73c1ac, 'Cheese and Chocolate Fondue Night', 'Set up a fondue pot at home and spend the evening dipping, snacking, and taking your time over a meal. It is indulgent, interactive, and the kind of dinner that stretches into a long, easy night. Add a good playlist and you are set.', '€€', 150, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab672716447d11f19dd676251f73c1ac, 'Cozy Bistro Dinner', 'Book a table at a small, warm restaurant with good food and no pressure. Dress up a little, order something you would not normally try, and take the evening slowly. A proper sit-down dinner with nowhere else to be.', '€€€', 120, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab67275c447d11f19dd676251f73c1ac, 'Coffee Shop Hopping', 'Pick two or three independent coffee shops in your city and spend the morning going between them. Order something different at each one, find your favorite, and let the day unfold from there. A slow, caffeinated, very easy date.', '€', 180, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab67278e447d11f19dd676251f73c1ac, 'Make Signature Cocktails for Each Other', 'Each of you picks three ingredients and challenges the other to build a cocktail around them. Look up techniques, taste as you go, and name your creations something ridiculous. A fun, slightly competitive way to spend an evening at home.', '€', 120, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6727b6447d11f19dd676251f73c1ac, 'Farm-to-Table Restaurant Experience', 'Book a table at a restaurant that sources locally and changes its menu with the seasons. Let the kitchen guide what you eat and pay attention to where things come from. Food tastes different when you know the story behind it.', '€€€', 150, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6727e8447d11f19dd676251f73c1ac, 'Dessert-Only Date', 'Skip dinner and go straight to dessert. Pick a patisserie, a dessert bar, or a spot known for one specific thing and make that the whole plan. Sometimes the best dates are the ones built around exactly what you feel like.', '€', 60, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab67281a447d11f19dd676251f73c1ac, 'Korean BBQ Night', 'Book a table at a Korean BBQ spot and spend the evening cooking at the table together. It is hands-on, social, and the kind of meal that takes time. Order more than you think you need and share everything.', '€€', 120, 1, 0xab5d858a447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a8636447d11f19dd676251f73c1ac, 'Sunset Picnic', 'Pack a blanket, some snacks, and your favorite drinks and find a spot with a view. Watch the sky turn pink and orange while the world slows down around you. Simple, free, and one of those dates you will keep coming back to.', '€', 150, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a8fd2447d11f19dd676251f73c1ac, 'Kayaking on a Calm Lake', 'Rent a kayak and spend a few hours out on the water with no particular destination. It is peaceful, a little physical, and a great way to disconnect from everything else. Bonus points if you find a quiet cove to stop and just float for a while.', '€€', 180, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a9036447d11f19dd676251f73c1ac, 'Sunrise Hike to a Scenic Overlook', 'Set the alarm early, pack coffee in a thermos, and hike to a viewpoint in time for sunrise. The early start feels worth it the moment the sky lights up. There is something about sharing that kind of quiet beauty that stays with you.', '€', 240, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a9072447d11f19dd676251f73c1ac, 'Bike Ride with a Picnic Stop', 'Plan a cycling route that ends somewhere worth stopping. Pack lunch, find a good patch of grass, and spend the middle of the day outside doing nothing in particular. Active enough to feel good, relaxed enough to actually enjoy it.', '€', 180, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a909a447d11f19dd676251f73c1ac, 'Visit a Botanical Garden', 'Spend an afternoon wandering through a botanical garden and taking in whatever is in season. Walk slowly, read the signs, and take photos of the things that catch your eye. A quiet, beautiful date that does not ask much of you.', '€', 120, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a90c2447d11f19dd676251f73c1ac, 'Stargazing with Blankets and Hot Drinks', 'Drive somewhere away from city lights, spread out a blanket, and spend the evening looking up. Download a star map app, find the constellations you know, and talk about everything and nothing. One of those dates that feels bigger than it is.', '€', 180, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a90ea447d11f19dd676251f73c1ac, 'Apple Picking or Berry Picking', 'Head to a local farm during harvest season and spend the morning picking fruit together. It is hands-on, outdoor, and ends with something to bring home and use. A date that works especially well in autumn when the light is just right.', '€', 150, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a911c447d11f19dd676251f73c1ac, 'Beach Walk Collecting Shells or Rocks', 'Take a long walk along the shoreline with no destination in mind. Pick up whatever catches your attention, skip stones, and let the sound of the water set the pace. The simplest dates are often the ones that feel most like yourselves.', '€', 120, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a9158447d11f19dd676251f73c1ac, 'Scenic Drive with a Playlist', 'Build a playlist together beforehand, pick a direction, and just drive. Stop wherever looks interesting, get out and explore, and let the road decide what kind of afternoon it becomes. No destination required.', '€', 180, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a918a447d11f19dd676251f73c1ac, 'Paddleboarding on a Calm Day', 'Rent paddleboards for the morning and take to the water at a pace that suits you. It requires just enough concentration to be fun and just enough balance to make you laugh. A good date for a warm, clear day.', '€€', 120, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a91b2447d11f19dd676251f73c1ac, 'Visit a Waterfall', 'Find a waterfall within driving distance and make it the destination for the day. Hike in, take photos, eat lunch by the water, and hike back out. There is something grounding about being near moving water that makes everything else quiet down.', '€', 240, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a91d0447d11f19dd676251f73c1ac, 'Fly Kites at a Park', 'Buy or dig out a kite, find an open field, and spend an afternoon running into the wind together. It is playful and a little ridiculous in the best way. A reminder that you do not need a plan to have a good time.', '€', 120, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a91f8447d11f19dd676251f73c1ac, 'Horseback Riding', 'Book a guided ride through a local trail and spend the morning on horseback. You do not need experience. Most places cater to beginners and the guides do the hard work. A slower, more unusual way to see the landscape around you.', '€€€', 120, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a9216447d11f19dd676251f73c1ac, 'Take a Ferry Ride to a Nearby Island', 'Find a ferry route near you and spend the day on the other side. Explore on foot, eat somewhere local, and take the last boat back. It has the feeling of a trip without the planning of one.', '€€', 360, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6a9234447d11f19dd676251f73c1ac, 'Riverwalk or Lakeside Trail', 'Find a trail along a river or lake and spend the morning walking it end to end. Pack snacks, take your time, and stop whenever something looks worth stopping for. One of those low-effort dates that always delivers.', '€', 150, 0, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6d848a447d11f19dd676251f73c1ac, 'Pottery Class', 'There is something oddly intimate about sitting across from each other, hands in clay, trying to make something that does not collapse. You will laugh a lot, focus hard, and walk away with something imperfect and completely yours. A date you will remember every time you see it on the shelf.', '€€€', 180, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da262447d11f19dd676251f73c1ac, 'Sip and Paint Night', 'Follow a guided painting class with drinks in hand and see how differently two people can interpret the same canvas. It is relaxed, creative, and just competitive enough to make it fun. No artistic experience needed. That is kind of the point.', '€€', 150, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da2da447d11f19dd676251f73c1ac, 'Scrapbooking or Memory-Lane Night', 'Print out photos, dig out ticket stubs and mementos, and spend the evening building something from your shared history. It is slower than it sounds and more emotional than you expect. A good date for a quiet night in.', '€', 180, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da316447d11f19dd676251f73c1ac, 'Glassblowing Class', 'Book a beginner glassblowing session and spend the afternoon working with molten glass under the guidance of a professional. It is unlike anything else you will try together. Equal parts terrifying and beautiful, and the results are genuinely impressive.', '€€€', 120, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da352447d11f19dd676251f73c1ac, 'Make a Vision Board or Bucket List', 'Gather magazines, print images, and spend the evening cutting and building a visual map of where you want to go together. Talk about what you each want, find the overlap, and put it somewhere you will both see it. A surprisingly meaningful way to spend an evening.', '€', 120, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da384447d11f19dd676251f73c1ac, 'Calligraphy or Lettering Class', 'Book a beginner calligraphy workshop and spend a couple of hours learning to write beautifully. It requires focus and patience but is deeply satisfying once something clicks. A quiet, hands-on date for people who like to make things.', '€€', 120, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da3b6447d11f19dd676251f73c1ac, 'Take a Dance Class Together', 'Sign up for a beginner session in salsa, swing, or ballroom and spend the evening learning to move together. You will step on each other and laugh about it and slowly start to find the rhythm. A date that keeps giving after it ends.', '€€', 90, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da3e8447d11f19dd676251f73c1ac, 'Write Love Letters and Read Them Aloud', 'Set a timer, write a letter to each other without showing the other, then sit down and read them out loud. It is vulnerable and warm and often surprising. One of those simple things that turns into a conversation you did not know you needed.', '€', 90, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da41a447d11f19dd676251f73c1ac, 'Create a Shared Playlist and Listen Start to Finish', 'Take turns adding songs until you have built something that feels like both of you. Then sit down, put it on, and listen all the way through. Talk about the ones that mean something. Music is one of the fastest ways to understand someone.', '€', 120, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da44c447d11f19dd676251f73c1ac, 'Woodworking Workshop', 'Book a beginner woodworking class and spend the afternoon building something small and real. It requires concentration and a little patience, and the finished object has a weight to it that other things do not. Something made with your hands always means more.', '€€€', 180, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da47e447d11f19dd676251f73c1ac, 'Couples Photography Challenge', 'Pick a theme, hand each other your phones, and spend an afternoon taking photos of the city through that lens. Compare the results at the end over coffee. You will see each other notice different things and that is always interesting.', '€', 180, 0, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da550447d11f19dd676251f73c1ac, 'Make Handmade Gifts for Each Other', 'Set a budget, a theme, and a time limit and make something for the other person using whatever materials you have. It does not have to be good. It just has to be thoughtful. The reveal at the end is always the best part.', '€', 180, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da5aa447d11f19dd676251f73c1ac, 'Write and Illustrate a Mini Comic Together', 'Come up with a character, a world, a problem, and a solution and divide the writing and drawing between you. It is silly and creative and a good excuse to be completely unserious for an afternoon. Keep it when you are done.', '€', 120, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da5dc447d11f19dd676251f73c1ac, 'Attend a Poetry Reading', 'Find a local open mic or poetry night and spend the evening listening to people share something personal. You do not have to perform. Just showing up is enough. A quieter, more unusual date that tends to spark good conversation afterward.', '€', 90, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab6da604447d11f19dd676251f73c1ac, 'Sculpture or Clay Workshop', 'Book a session at a local art studio and spend the afternoon working with clay or sculpting materials. There is no pressure to make something recognizable. The point is to use your hands and pay attention to what you are making together.', '€€', 150, 1, 0xab5e4fd8447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab706132447d11f19dd676251f73c1ac, 'Comedy Show', 'Book tickets to a local stand-up night and give yourselves permission to just laugh. There is something great about sharing that kind of unfiltered joy in a room full of strangers. Grab drinks beforehand and make a proper night of it.', '€€', 120, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab706c36447d11f19dd676251f73c1ac, 'Museum Visit', 'Pick a museum neither of you has been to and explore at your own pace. Read the plaques, skip the ones that bore you, and stop at whatever pulls you in. The conversations that happen between the exhibits are usually the best part.', '€', 180, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab706ca4447d11f19dd676251f73c1ac, 'Outdoor Movie Night or Drive-In', 'Find an outdoor screening or drive-in near you and spend the evening watching something under the sky. Bring snacks, wrap up warm if needed, and enjoy the feeling of a cinema that breathes. A classic for a reason.', '€€', 150, 0, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d1b2447d11f19dd676251f73c1ac, 'Local Theater Performance', 'Book tickets to a play or performance at a nearby theater and dress up a little for the occasion. You do not need to be a theater person to enjoy it. Good storytelling works on everyone, and it gives you plenty to talk about after.', '€€', 150, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d234447d11f19dd676251f73c1ac, 'Concert or Live Music Show', 'Buy tickets to see someone you both love or are curious about and spend the evening in the crowd together. Live music has an energy that recordings cannot replicate. A date that tends to leave you both feeling something.', '€€€', 180, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d266447d11f19dd676251f73c1ac, 'Visit a Planetarium', 'Book a show at a local planetarium and spend an hour lying back and looking up at a projected universe. It is the kind of experience that makes everything feel appropriately small and beautiful at the same time. A quiet, perspective-shifting date.', '€', 90, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d298447d11f19dd676251f73c1ac, 'Explore City Murals', 'Map out the murals in your city and spend an afternoon walking between them. Take photos, look up the artists, and talk about what you each respond to. A free, slow, visually interesting way to see the city you live in differently.', '€', 180, 0, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d36a447d11f19dd676251f73c1ac, 'Attend a Film Festival', 'Check what film festivals are happening near you and book tickets to a screening. You will likely see something unexpected, and that is the point. Discussing a film you watched together for the first time is one of the best kinds of conversation.', '€€', 150, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d3ce447d11f19dd676251f73c1ac, 'Visit a Famous Filming Location', 'Find a spot near you that has been used in a film or TV show you both love and make a day of visiting it. Take photos, reenact a scene, and notice how different it looks in real life. A fun, slightly nerdy date with a good story attached.', '€', 180, 0, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d414447d11f19dd676251f73c1ac, 'Nighttime City Tour', 'Book a walking or bus tour of your city after dark and see familiar places from a different angle. You will learn things about where you live that you did not know before. A good option for a weekend evening when you want to feel like tourists.', '€€', 120, 0, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d446447d11f19dd676251f73c1ac, 'Attend a Lantern Festival', 'Find a lantern festival happening near you and spend the evening watching hundreds of lights lift into the sky. It is one of those experiences that is hard to describe and easy to feel. Bring a camera and arrive early for a good spot.', '€€', 180, 0, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d46e447d11f19dd676251f73c1ac, 'Watch Fireworks Together', 'Find out where the nearest fireworks display is happening and get there early enough to find a good spot. Bring a blanket, something to drink, and nothing else. There is a reason this is a classic. It still works every time.', '€', 120, 0, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d4aa447d11f19dd676251f73c1ac, 'Art Gallery or Art Walk', 'Visit a local gallery or join an art walk event and spend the evening moving through rooms of work made by people nearby. You do not need to understand everything you see. Just noticing what you react to is enough.', '€', 120, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d4d2447d11f19dd676251f73c1ac, 'Open Mic Night', 'Find a local open mic and spend the evening watching people be brave enough to perform. The range is always wide and the atmosphere is always warm. A relaxed, low-key date that tends to surprise you.', '€', 120, 1, 0xab5e9830447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab70d4fa447d11f19dd676251f73c1ac, 'Visit an Aquarium', 'Spend an afternoon at an aquarium moving slowly through dimly lit rooms full of water and life. Watch jellyfish drift, sharks glide, and tiny fish dart through coral. It is calming in a way that is hard to explain and a good reminder of how much of the world exists completely without us.', '€€', 150, 1, 0xab5df772447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73ae96447d11f19dd676251f73c1ac, 'Indoor Rock Climbing', 'Strap in, chalk up, and take turns cheering each other up the wall. It is physical, a little scary, and surprisingly good for trust. Most climbing gyms offer beginner routes so no experience needed. Just a willingness to try.', '€€', 120, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b882447d11f19dd676251f73c1ac, 'Ice Skating', 'Lace up and take to the ice, wobbly knees and all. It is the kind of date that feels straight out of a winter film. Cold air, warm hands, and a lot of laughing at each other. Outdoor rinks in particular have a magic to them that is hard to beat.', '€', 90, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b8be447d11f19dd676251f73c1ac, 'Mini Golf', 'Find a mini golf course and spend the afternoon working through eighteen holes of creative obstacles and questionable technique. It is light, fun, and just competitive enough to keep things interesting. A reliable date that always delivers.', '€', 90, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b8f0447d11f19dd676251f73c1ac, 'Bowling Night', 'Book a lane, rent the shoes, and spend the evening bowling badly and celebrating wildly. It does not matter how good you are. The lanes are loud, the drinks are cold, and the energy is always right for a good time.', '€', 120, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b918447d11f19dd676251f73c1ac, 'Trampoline Park', 'Book a session at a trampoline park and spend an hour jumping, bouncing, and being completely ridiculous together. It is exhausting in the best way and nearly impossible to do without laughing. A date that makes you feel like kids again.', '€€', 90, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b936447d11f19dd676251f73c1ac, 'Laser Tag', 'Book a session and spend twenty minutes trying to outsmart each other in a dark, neon-lit arena. It is fast, silly, and the kind of competitive fun that brings out a side of people you do not often see. Good for anyone who likes to win.', '€', 60, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b95e447d11f19dd676251f73c1ac, 'Arcade Night', 'Find a good arcade and spend the evening working through games, collecting tickets, and competing for bragging rights. Old-school arcades with classics like air hockey and claw machines are the best. A date that does not take itself seriously.', '€', 120, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b97c447d11f19dd676251f73c1ac, 'Tennis or Pickleball', 'Book a court for an hour and take a racket sport for a spin. You do not need to be good at it. Half the fun is figuring it out together and deciding who is secretly more competitive. A good excuse to be outside and active without it feeling like exercise.', '€', 60, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b9a4447d11f19dd676251f73c1ac, 'Roller Skating', 'Find a roller rink or a smooth outdoor path and spend the afternoon on wheels. It is retro, a little wobbly, and the kind of date that comes with a built-in excuse to hold on to each other. Wear knee pads if you have them.', '€', 90, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b9cc447d11f19dd676251f73c1ac, 'Go for a Run or Work Out Together', 'Pick a scenic route or a park you both like and go for a run or outdoor workout together. It is not glamorous but it is energizing and oddly connecting. Finish with a good breakfast and the rest of the day feels earned.', '€', 90, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73b9ea447d11f19dd676251f73c1ac, 'Scavenger Hunt Around Your City', 'Design a scavenger hunt for each other using landmarks, clues, and challenges that are personal to your relationship. Split the planning in advance and take turns being the guide. A date that requires effort and pays back double.', '€', 180, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73e2f8447d11f19dd676251f73c1ac, 'Fitness Dance Class', 'Sign up for a high-energy dance fitness class and spend an hour moving together without overthinking it. Zumba, salsa fitness, or hip hop cardio all work well. It is loud, joyful, and a great way to shake off a long week.', '€€', 60, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73e352447d11f19dd676251f73c1ac, 'Do Yoga or Stretching Together', 'Find a beginner yoga video or book a class and spend an hour moving slowly and intentionally together. It is grounding, gentle, and a good reset after a busy stretch. Easier at home than you might think, and a good excuse to breathe.', '€', 60, 1, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73e384447d11f19dd676251f73c1ac, 'Obstacle Course or Ropes Course', 'Book a session at an outdoor ropes course or obstacle park and spend the morning helping each other through challenges that require real teamwork. It is physical, a little nerve-wracking, and leaves you both feeling like you can handle things together.', '€€€', 180, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36'),
(0xab73e3ac447d11f19dd676251f73c1ac, 'Lawn Games at a Park', 'Pack a bag with pétanque, frisbee, badminton, or whatever you have and head to a park for an afternoon of low-stakes competition. Bring a picnic to stretch it into a full day. The kind of simple, unhurried date that feels exactly right.', '€', 180, 0, 0xab5edc96447d11f19dd676251f73c1ac, '2026-04-30 12:16:36');
